import com.acmehealth.priorauth.model.PriorAuthRequest;

import java.time.LocalDate;

/** One row of the pending list as the reviewer screen receives it (JSON). */
public record PendingRequestResponse(
        String id,
        String tenantId,
        String service,
        String status,
        LocalDate receivedAt,
        int ageBusinessDays,
        boolean overLimit,
        String ageLabel) {

    /** {@code overLimit} is true when the age is more than {@code thresholdDays}. */
    public static PendingRequestResponse from(PriorAuthRequest request, int ageBusinessDays, int thresholdDays) {
        boolean overLimit = ageBusinessDays > thresholdDays;
        String ageLabel = ageBusinessDays + " bd" + (overLimit ? " OVER " + thresholdDays : "");
        return new PendingRequestResponse(request.id(), request.tenantId(), request.service(), request.status(),
                request.receivedAt(), ageBusinessDays, overLimit, ageLabel);
    }
}
